head.script:
/* ★Wcraft guide★    
스크립트 수작업 유의사항
*/


//★Wcraft guide★ include부분 주석처리 -> include("../js/PopupCalendar.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/utils.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/libRoundPanel.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/common.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/list_common.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/session.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/stf.js");

//종목기준명 등록 호출
scwin.vScrenID = "ULDINS91200.xml";
scwin.param1 = "";
scwin.param2 = "";
scwin.param3 = "";
scwin.cnt = 0;
scwin.crud = "";
scwin.prevRow = -1;
scwin.onpageload = function() {
    scwin.gform_onload();
};
scwin.onpageunload = function() {
};

/********************************************** 
 * 함수명   : ins_search
 * 설명       : 종목기준명 조회하기 .
 ***********************************************/
scwin.ins_search = function(isurcd) {
    var url = "/listingCommon.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01 + "&method=listGeneralForDynamicName" + "&outputMessageId=ULDINS91200_LIST_OUT" + "&service=krx.lds.ins.listingcommon.services.ListingCommonApp" + "&queryId=lds.ins.common.select.listIsuNmInquiry" + "&{P}param01=" + isurcd + "&{P}param02=" + scwin.param3;
    dts_List.DataID = encodeURI(url);
    dts_List.reset();
    $c.cm.ShowWin(grd_Grid); // 그리드명을 표기

};

/********************************************** 
 * 함수명   : ins_process
 * 설명       : 종목기준명 저장 , 수정하기   . screenProcsTpCd 02,03
 ***********************************************/
scwin.ins_process = function(screenProcsTpCd) {
    //alert("dts_Out.Text " +dts_Out.Text);
    //alert("dts_Out.ISUR_CD " +dts_Out.NameValue(dts_Out.RowPosition,"ISUR_NM"));
    if (scwin.cnt == 0) {
        //fn_SetHeader() ; 

    } else {
        if (!$c.cp.isModified(dts_List)) {
            $c.win.alert("변경된 데이터가 없습니다.");
            return;
        }
    }
    if (txb_NEW_BAS_ISU_NM.getValue() == "" || txb_NEW_BAS_ISU_NM.getValue().indexOf(" ") == "") {
        $c.win.alert($c.stf.getMessageParam("MSG-A005", "한글기준명"));
        txb_NEW_BAS_ISU_NM.focus();
        return;
    }
    if (!$c.stf.checkMaxLength(txb_NEW_BAS_ISU_NM, 60, "한글기준명")) {
        txb_NEW_BAS_ISU_NM.focus();
        return false;
    }
    if (txb_BAS_ISU_ABBRV.getValue() == "" || txb_BAS_ISU_ABBRV.getValue().indexOf(" ") == "") {
        $c.win.alert($c.stf.getMessageParam("MSG-A005", "한글기준약명"));
        txb_BAS_ISU_ABBRV.focus();
        return;
    }
    if (!$c.stf.checkMaxLength(txb_BAS_ISU_ABBRV, 20, "한글기준약명")) {
        txb_BAS_ISU_ABBRV.focus();
        return false;
    }
    if (txb_BAS_ISU_ENG_NM.getValue() == "" || txb_BAS_ISU_ENG_NM.getValue().indexOf(" ") == "") {
        $c.win.alert($c.stf.getMessageParam("MSG-A005", "영문기준명"));
        txb_BAS_ISU_ENG_NM.focus();
        return;
    }
    if (!$c.stf.checkMaxLength(txb_BAS_ISU_ENG_NM, 60, "영문기준명")) {
        txb_BAS_ISU_ENG_NM.focus();
        return false;
    }
    if (txb_BAS_ISU_ENG_ABBRV.getValue() == "" || txb_BAS_ISU_ENG_ABBRV.getValue().indexOf(" ") == "") {
        $c.win.alert($c.stf.getMessageParam("MSG-A005", "영문기준약명"));
        txb_BAS_ISU_ENG_ABBRV.focus();
        return;
    }
    if (!$c.stf.checkMaxLength(txb_BAS_ISU_ENG_ABBRV, 20, "영문기준약명")) {
        txb_BAS_ISU_ENG_ABBRV.focus();
        return false;
    }

    //alert(getObjectValue(cmb_ELS_DLS_TP_CD));

    //ELSDLS구분코드 필수
    if (scwin.param3 == "1" && $c.stf.getObjectValue(cmb_ELS_DLS_TP_CD) == "") {
        $c.win.alert("ELS/DLS, DLS/DLB구분이 선택되지 않았습니다.");
        cmb_ELS_DLS_TP_CD.focus();
        return false;
    }
    if (scwin.cnt == 0) {

    } else {
        if (screenProcsTpCd == "02") {
            // 등록시 중복체크 
            if (scwin.fn_dup() == false) {
                $c.win.alert("한글기준명 중복입니다.");
                return;
            }
        }
    }
    trs_save.Action = "/CmmInfoAction.do?method=processIsuNm" + "&SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + screenProcsTpCd;
    trs_save.KeyName = "toinb_dataid4";
    trs_save.KeyValue = "JSP(I:pInput=dts_List)";
    trs_save.Parameters = "EMP_NO=" + js_emp_no + ",EMP_NM=" + js_emp_nm;
    trs_save.Post();
};


/********************************************** 
 * 함수명   : ins_remove
 * 설명       : 종목기준명 삭제하기   . screenProcsTpCd 04
 ***********************************************/
scwin.ins_remove = function() {
    if (dts_List.getTotalRow() == 1) {
        $c.win.alert("정보가 1건입니다. 삭제불가입니다. 수정만 가능합니다.");
        return;
    }
    var rtn = confirm('내용을 삭제 하시겠습니까?');
    if (rtn == 1) // [확인] 버튼이 눌려졌을 경우

    {

        //dts_ListDelete.setDataHeader(); // W-Craft 주석처리 및 필요시 asis 파라미터 확인 
        dts_ListDelete.insertRow();
        dts_ListDelete.setCellData(1, "ISUR_CD", dts_List.getCellData(dts_List.getRowPosition(), "ISUR_CD"));
        dts_ListDelete.setCellData(1, "BAS_ISU_NM", dts_List.getCellData(dts_List.getRowPosition(), "BAS_ISU_NM"));

        //alert("dts_ListDelete.ISUR_CD "+ dts_ListDelete.NameValue(dts_ListDelete.RowPosition,"ISUR_CD"));

        trs_remove.Action = "/CmmInfoAction.do?method=processIsuNm" + "&SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_04;
        trs_remove.KeyName = "toinb_dataid4";
        trs_remove.KeyValue = "JSP(I:pInput=dts_ListDelete)";
        trs_remove.Post();
    }
};



/********************************************** 
 * 함수명   : fn_new
 * 설명       : 신규등록을 위한 dataset 세팅 
 ***********************************************/
scwin.fn_new = function() {
    dts_List.insertRow();
    dts_List.setCellData(dts_List.getRowPosition(), "ISUR_CD", scwin.param1);
    dts_List.setCellData(dts_List.getRowPosition(), "COM_NM", scwin.param2);
    fn_CtrlBtn("insert");
};



/********************************************** 
 * 함수명   : fn_dup
 * 설명       :  한글기준명 중복검사 
 ***********************************************/
scwin.fn_dup = function() {
    var dupcnt = 0;
    for (var i = 1; i <= dts_List.getTotalRow(); i++) {
        //alert(dts_List.NameString(i, "BAS_ISU_NM") + " " +txb_NEW_BAS_ISU_NM.value);
        if (dts_List.getCellData(i, "BAS_ISU_NM") == txb_NEW_BAS_ISU_NM.getValue()) {
            dupcnt++;
        }
    }
    //alert("dupcnt " +dupcnt);
    if (dupcnt == 0) {
        return true;
    } // 중복아님 
    else {
        return false;
    } // 중복 

};
scwin.dts_List_OnLoadCompleted = function(rowcount) {
    if (rowcount == 0) {
        fn_CtrlBtn("no_data");
    } else {
        $c.stf.setObjectValue(cmb_ELS_DLS_TP_CD, dts_List.getCellData(dts_List.getRowPosition(), "ELS_DLS_TP_CD"));
    }
    scwin.cnt = rowcount;
    $c.cm.CloseWin(rowcount, grd_Grid); //데이터 로딩중닫기 및 조회없음 처리	

};
scwin.dts_List_OnLoadError = function() {
    $c.stf.alert_error(dts_List);
    scwin.cnt = 0;
    $c.cm.CloseWin(0, grd_Grid); //데이터 로딩중닫기 및 조회없음 처리	
    fn_CtrlBtn("no_data");
};
scwin.gform_onload = function() {
    $c.cm.PanelToGroupBox(panel_1);
    ins_combo_set(dts_Cod, scwin.vScrenID, SCREN_PROCS_TP_CD_01, "03478", "SEL"); // 03478 - ELS DLS 구분  ELS_DLS_TP_CD  2013.11.25 ELSDLS구분코드 변경      
    $c.stf.showObj(txb_BAS_ISU_NM, false);
    $c.stf.showObj(btn_search, false);
    var sd = $c.frame.path("../").scwin.vScrenID;
    if (sd == "ULDINS10100.gfm" || sd == "ULDINS10900.gfm" || sd == "ULDINS15100.gfm" || sd == "ULDINS16200.gfm" ||
        sd == "ULDINS10800.gfm" || sd == "ULDINS16100.gfm") {
        // 채권 접수 , 채권관리 , CP전자단기사채 접수 ,  CP전자단기사채 관리
        // CD 접수,관리
        $c.stf.showObj(cmb_ELS_DLS_TP_CD, false);
        $c.stf.showObj(label_8, false);
        $c.cm.setColumnProp(grd_Grid, "ELS_DLS_NM", "Show", false);
        $c.cm.setColumnProp(grd_Grid, "BAS_ISU_NM", "width", "200");
        scwin.param3 = "0";
    } else if (sd == "ULDINS10200.gfm" || sd == "ULDINS15200.gfm") {
        var ELS_DLS_TP_CD = $c.stf.getObjectValue($c.frame.path("../").cmb_ELS_DLS_TP_CD);
        //alert(ELS_DLS_TP_CD);
        // elsdls 접수 , 관리 
        $c.stf.showObj(cmb_ELS_DLS_TP_CD, true);
        $c.stf.showObj(label_8, true);
        $c.cm.setColumnProp(grd_Grid, "ELS_DLS_NM", "Show", true);
        scwin.param3 = "1";
    }
    var arrPar = new Array();
    var parentWin = $c.frame.path("../");
    var fn_GetPar = parentWin.fn_GetParam;
    if (fn_GetPar != undefined) {
        fn_GetPar(arrPar);
        scwin.param1 = ((arrPar.length >= 1) && (arrPar[0] != undefined) ? arrPar[0] : "");
        scwin.param2 = ((arrPar.length >= 1) && (arrPar[1] != undefined) ? arrPar[1] : "");
    }
    //alert(param2);
    scwin.ins_search(scwin.param1);
};
scwin.btn_modify_onclick = function() {
    scwin.ins_process("03");
};
scwin.trs_modify_OnSuccess = function() {
    $c.win.alert($c.stf.getMessageParam("MSG-A001", "종목기준명 수정"));
    scwin.ins_search(scwin.param1);
    //frame.CloseFrame();

};
scwin.trs_modify_OnFail = function() {
    alert_tr_error(trs_modify);
    scwin.ins_search(scwin.param1);
};
scwin.trs_save_OnSuccess = function() {
    $c.win.alert($c.stf.getMessageParam("MSG-A001", "종목기준명 등록"));
    scwin.ins_search(scwin.param1);
    //frame.CloseFrame();

};
scwin.trs_save_OnFail = function() {
    alert_tr_error(trs_save);
    scwin.ins_search(scwin.param1);
};
scwin.trs_remove_OnSuccess = function() {
    $c.win.alert($c.stf.getMessageParam("MSG-A001", "종목기준명 삭제"));
    scwin.ins_search(scwin.param1);
    //frame.CloseFrame();

};
scwin.trs_remove_OnFail = function() {
    alert_tr_error(trs_remove);
    scwin.ins_search(scwin.param1);
};
scwin.btn_save_onclick = function() {
    scwin.ins_process("02");
};
scwin.btn_delete_onclick = function() {
    scwin.ins_remove();
};
scwin.btn_close_onclick = async function() {
    await $c.frame.CloseFrame();
};
scwin.btn_modify_onclick = function() {
    scwin.ins_process("03");
};
scwin.btn_search_onclick = function() {
    scwin.ins_search(scwin.param1);
};
scwin.dts_Cod_OnLoadCompleted = function(rowcount) {
    //alert('dts_Cod.OnLoadCompleted('+rowcount+')');

};
scwin.grd_Grid_OnDblClick = async function(row, colid) {
    var BAS_ISU_NM = dts_List.getCellData(row, "BAS_ISU_NM");
    var BAS_ISU_ABBRV = dts_List.getCellData(row, "BAS_ISU_ABBRV");
    var BAS_ISU_ENG_NM = dts_List.getCellData(row, "BAS_ISU_ENG_NM");
    var BAS_ISU_ENG_ABBRV = dts_List.getCellData(row, "BAS_ISU_ENG_ABBRV");
    $c.frame.path("../").ins_popupRtn_val4(BAS_ISU_NM, BAS_ISU_ABBRV, BAS_ISU_ENG_NM, BAS_ISU_ENG_ABBRV);
    await $c.frame.CloseFrame();
};
scwin.btn_new_onclick = function() {
    scwin.fn_new();
};
scwin.dts_List_OnRowPosChanged = function(row) {
    dts_List.undoRow(scwin.prevRow);
    scwin.prevRow = row;
    fn_CtrlBtn("update");
};
scwin.btn_isunm_confirm_onclick = function() {
    ins_popupOpen("", "", "ULDINS90600", "주권 종목코드", "730", "505");
};
